            { title: "The Local Market", lines:[ { speaker:"Albert", text:"This is the square ___ the local farmers sell their products.", options:["where","when","who"], a:"where" }, { speaker:"Celine", text:"I noticed that prices here are ___ than at the supermarket.", options:["cheaper","the cheapest","more cheap"], a:"cheaper" }, { speaker:"Albert", text:"Yes, and the quality is ___ as well.", options:["better","the best","gooder"], a:"better" }, { speaker:"Celine", text:"Supporting local producers, ___ helps our economy, is a great initiative.", options:["which","who","that"], a:"which" }, { speaker:"Albert", text:"I believe it’s the ___ way to shop during hard times.", options:["smartest","smarter","most smart"], a:"smartest" } ] },
            { title: "A New Business", lines:[ { speaker:"Celine", text:"Did you hear about the cafe ___ opened yesterday?", options:["which","who","whose"], a:"which" }, { speaker:"Albert", text:"Yes, the owner, ___ went bankrupt last year, started it.", options:["who","whom","which"], a:"who" }, { speaker:"Celine", text:"That shows incredible ___ to try again.", options:["resilience","budget","recession"], a:"resilience" }, { speaker:"Albert", text:"It is definitely the ___ courageous thing to do.", options:["most","more","much"], a:"most" }, { speaker:"Celine", text:"I agree. We should support local businesses ___ are struggling.", options:["that","where","who"], a:"that" } ] },
            { title: "Managing Money", lines:[ { speaker:"Albert", text:"We need to set a ___ for our monthly expenses.", options:["budget","recession","tragedy"], a:"budget" }, { speaker:"Celine", text:"Yes, the ___ hits low-income families the hardest.", options:["inflation","optimism","silver lining"], a:"inflation" }, { speaker:"Albert", text:"The people ___ salaries haven't changed are suffering the most.", options:["whose","whom","which"], a:"whose" }, { speaker:"Celine", text:"It is the ___ economic period I have ever seen.", options:["hardest","harder","more hard"], a:"hardest" }, { speaker:"Albert", text:"We must shop at the store ___ prices are lower.", options:["where","when","whose"], a:"where" } ] }
